/**
 * Catalog Data Reader for Static JSON Export
 * 
 * This module reads products and categories from a static JSON file
 * generated by the backend export functionality.
 * 
 * The JSON file is generated at build time using:
 *   npm run import-products
 * 
 * This approach provides:
 * - Perfect SEO (static HTML pages)
 * - Fast loading (no API calls at runtime)
 * - Easy to update (just rebuild)
 */

import path from 'path';
import fs from 'fs';

// Type definitions for product data
export interface ProductVariant {
  id: number;
  sku: string;
  title: string | null;
  price: number;
  mrp: number;
  cost_price: number | null;
  stock: number;
  weight_grams: number | null;
}

export interface ProductImage {
  id: number;
  url: string;
  path: string;
  is_primary: boolean;
  alt: string | null;
}

export interface ProductCategory {
  id: number;
  name: string;
  slug: string;
}

export interface Product {
  id: number;
  name: string;
  slug: string;
  description: string | null;
  seo_title: string | null;
  seo_description: string | null;
  brand: string | null;
  tags: string[];
  weight_grams: number | null;
  is_cod_allowed: boolean;
  hsn_code: string | null;
  gst_rate: number | null;
  category: ProductCategory | null;
  variants: ProductVariant[];
  images: ProductImage[];
  updated_at: string | null;
  created_at: string | null;
}

export interface Category {
  id: number;
  name: string;
  slug: string;
  description: string | null;
  parent_id: number | null;
  position: number | null;
  is_active: boolean;
}

export interface CatalogMeta {
  store_id?: number;
  store_name?: string;
  store_slug?: string;
  exported_at: string;
  product_count: number;
  category_count: number;
}

export interface CatalogData {
  products: Product[];
  categories: Category[];
  meta: CatalogMeta;
}

// Cache for performance during build
let cachedData: CatalogData | null = null;

/**
 * Get the path to the products JSON file
 */
function getJsonPath(): string {
  // Try multiple possible locations
  const possiblePaths = [
    path.join(process.cwd(), 'public', 'products.json'),
    path.join(process.cwd(), '..', 'public', 'products.json'),
    path.join(process.cwd(), 'data', 'products.json'),
    path.join(process.cwd(), 'products.json'),
  ];

  for (const filePath of possiblePaths) {
    if (fs.existsSync(filePath)) {
      return filePath;
    }
  }

  // Default location
  return path.join(process.cwd(), 'public', 'products.json');
}

/**
 * Read catalog data from JSON file
 * 
 * @throws Error if JSON file is not found or invalid
 */
export function getCatalogData(): CatalogData {
  // Return cached data if available
  if (cachedData) {
    return cachedData;
  }

  const jsonPath = getJsonPath();

  // Check if file exists
  if (!fs.existsSync(jsonPath)) {
    throw new Error(
      `Products JSON file not found at: ${jsonPath}\n` +
      `Please run: npm run import-products\n` +
      `Or check if the file exists at the expected location.`
    );
  }

  // Read file content
  const fileContent = fs.readFileSync(jsonPath, 'utf-8');
  
  // Parse JSON (remove any comments if present)
  // Some JSON files might have comments at the top
  const jsonContent = fileContent.replace(/^\/\*[\s\S]*?\*\//, '');
  
  let data: CatalogData;
  try {
    data = JSON.parse(jsonContent) as CatalogData;
  } catch (error) {
    throw new Error(
      `Failed to parse products JSON file at: ${jsonPath}\n` +
      `Error: ${error instanceof Error ? error.message : String(error)}`
    );
  }

  // Validate data structure
  if (!data.products || !Array.isArray(data.products)) {
    throw new Error('Invalid catalog data: missing or invalid products array');
  }

  if (!data.categories || !Array.isArray(data.categories)) {
    // If categories are missing, use empty array
    data.categories = [];
  }

  if (!data.meta) {
    data.meta = {
      exported_at: new Date().toISOString(),
      product_count: data.products.length,
      category_count: data.categories.length,
    };
  }

  // Cache the data
  cachedData = data;

  return data;
}

/**
 * Reset the cached data (useful for testing)
 */
export function resetCache(): void {
  cachedData = null;
}

/**
 * Get all products
 */
export function getProducts(): Product[] {
  return getCatalogData().products;
}

/**
 * Get all categories
 */
export function getCategories(): Category[] {
  return getCatalogData().categories;
}

/**
 * Get catalog metadata
 */
export function getMeta(): CatalogMeta {
  return getCatalogData().meta;
}

/**
 * Get a single product by ID
 */
export function getProductById(id: number): Product | null {
  const products = getProducts();
  return products.find(p => p.id === id) || null;
}

/**
 * Get a single product by slug
 */
export function getProductBySlug(slug: string): Product | null {
  const products = getProducts();
  return products.find(p => p.slug === slug) || null;
}

/**
 * Get products by category ID
 */
export function getProductsByCategoryId(categoryId: number): Product[] {
  const products = getProducts();
  return products.filter(p => p.category?.id === categoryId);
}

/**
 * Get products by category slug
 */
export function getProductsByCategorySlug(categorySlug: string): Product[] {
  const [products, categories] = [getProducts(), getCategories()];
  const category = categories.find(c => c.slug === categorySlug);
  
  if (!category) {
    return [];
  }
  
  return products.filter(p => p.category?.id === category.id);
}

/**
 * Search products by query
 */
export function searchProducts(query: string): Product[] {
  const products = getProducts();
  const q = query.toLowerCase().trim();
  
  if (!q) {
    return products;
  }
  
  return products.filter(p => {
    const nameMatch = p.name.toLowerCase().includes(q);
    const descMatch = p.description?.toLowerCase().includes(q);
    const tagMatch = p.tags?.some(t => t.toLowerCase().includes(q));
    const seoTitleMatch = p.seo_title?.toLowerCase().includes(q);
    const seoDescMatch = p.seo_description?.toLowerCase().includes(q);
    const brandMatch = p.brand?.toLowerCase().includes(q);
    const categoryMatch = p.category?.name.toLowerCase().includes(q);
    
    return nameMatch || descMatch || tagMatch || seoTitleMatch || seoDescMatch || brandMatch || categoryMatch;
  });
}

/**
 * Get featured/best products (e.g., first N products or by some criteria)
 */
export function getFeaturedProducts(limit: number = 8): Product[] {
  const products = getProducts();
  // Sort by created_at descending (newest first) and take first N
  return [...products]
    .sort((a, b) => {
      const dateA = new Date(a.created_at || '').getTime();
      const dateB = new Date(b.created_at || '').getTime();
      return dateB - dateA;
    })
    .slice(0, limit);
}

/**
 * Get products on sale (where price < mrp)
 */
export function getProductsOnSale(): Product[] {
  const products = getProducts();
  return products.filter(p => 
    p.variants.some(v => v.price < v.mrp)
  );
}

/**
 * Get products by brand
 */
export function getProductsByBrand(brandSlug: string): Product[] {
  const products = getProducts();
  return products.filter(p => 
    p.brand?.toLowerCase() === brandSlug.toLowerCase()
  );
}

/**
 * Get all unique brands
 */
export function getAllBrands(): string[] {
  const products = getProducts();
  const brands = products
    .map(p => p.brand)
    .filter((brand): brand is string => brand !== null && brand !== '')
    .filter((value, index, self) => self.indexOf(value) === index);
  
  return brands.sort();
}

/**
 * Get all unique tags
 */
export function getAllTags(): string[] {
  const products = getProducts();
  const tags: string[] = [];
  
  products.forEach(p => {
    p.tags?.forEach(tag => {
      if (tag && !tags.includes(tag)) {
        tags.push(tag);
      }
    });
  });
  
  return tags.sort();
}

/**
 * Get category by ID
 */
export function getCategoryById(id: number): Category | null {
  const categories = getCategories();
  return categories.find(c => c.id === id) || null;
}

/**
 * Get category by slug
 */
export function getCategoryBySlug(slug: string): Category | null {
  const categories = getCategories();
  return categories.find(c => c.slug === slug) || null;
}

/**
 * Get child categories of a parent category
 */
export function getChildCategories(parentId: number): Category[] {
  const categories = getCategories();
  return categories.filter(c => c.parent_id === parentId);
}

/**
 * Get parent category of a category
 */
export function getParentCategory(categoryId: number): Category | null {
  const categories = getCategories();
  const category = categories.find(c => c.id === categoryId);
  
  if (!category?.parent_id) {
    return null;
  }
  
  return categories.find(c => c.id === category.parent_id) || null;
}

/**
 * Get category tree (hierarchical categories)
 */
export function getCategoryTree(): Category[] {
  const categories = getCategories();
  const roots = categories.filter(c => c.parent_id === null);
  
  function buildTree(category: Category): Category & { children?: Category[] } {
    const children = categories.filter(c => c.parent_id === category.id);
    return {
      ...category,
      children: children.map(buildTree),
    };
  }
  
  return roots.map(buildTree) as Category[];
}

/**
 * Get products in stock
 */
export function getProductsInStock(): Product[] {
  const products = getProducts();
  return products.filter(p => 
    p.variants.some(v => v.stock > 0)
  );
}

/**
 * Get products out of stock
 */
export function getProductsOutOfStock(): Product[] {
  const products = getProducts();
  return products.filter(p => 
    p.variants.every(v => v.stock <= 0)
  );
}

/**
 * Get lowest priced products
 */
export function getLowestPricedProducts(limit: number = 8): Product[] {
  const products = getProducts();
  return [...products]
    .sort((a, b) => {
      const priceA = Math.min(...a.variants.map(v => v.price));
      const priceB = Math.min(...b.variants.map(v => v.price));
      return priceA - priceB;
    })
    .slice(0, limit);
}

/**
 * Get highest priced products
 */
export function getHighestPricedProducts(limit: number = 8): Product[] {
  const products = getProducts();
  return [...products]
    .sort((a, b) => {
      const priceA = Math.max(...a.variants.map(v => v.price));
      const priceB = Math.max(...b.variants.map(v => v.price));
      return priceB - priceA;
    })
    .slice(0, limit);
}
